#testing/debugging code
st=0 #starting section for debugging. Normal use leave at 0
define :check do |durs| #check total duration of a given part
  total=0
  durs.each do |x|
    total += x
  end
  return total
end

define :cklen do |n,d| #check number of entries in a given note/duration pair of lists
puts n.length,d.length
end
 
define :mplay do |notes,durs,channel,tr,vel=100| #send list of midi notes/durations
  for x in 0..notes.length-1
    if notes[x].respond_to?(:each)
      notes[x].each do |n|
        midi note(n)+tr,sustain: durs[x],channel: channel,velocity: vel
      end
    else
      midi note(notes[x])+tr,sustain: durs[x],channel: channel,velocity: vel
    end
    sleep durs[x]
  end
end

#switch output depending upon whether using midi or internal piano
if midiplay then
live_audio :vmpk,:stop #clear any existing audio input
sleep 1
use_midi_defaults port: "iac_driver_sonic-pi"#iac driver sonicpi"
3.times do |i|
midi_pc 6,channel: i+1 #set chans 1-3 to harpsichord (pc 6)
end
#output midi channels 1-3 with parts 3-5
in_thread do
for i in st..a3.length-1
use_bpm c3[i]
mplay a3[i],b3[i],1,0
end
end

in_thread do
for i in st..a4.length-1
use_bpm c4[i]
mplay a4[i],b4[i],2,0
end
end

in_thread do
